  --primary-border: #FED7AA;
  --accent: #10B981;
  --accent-light: #ECFDF5;
  --bg: #FAFAF9;
  --surface: #FFFFFF;
  --text-main: #1C1917;
  --text-muted: #78716C;
  --border: #E7E5E4;
