.modal-backdrop { position: fixed; inset: 0; background: rgba(0,0,0,0.5); display: none; align-items: center; justify-content: center; z-index: 100; }
.modal-backdrop.open { display: flex; }
.modal-card { background: #fff; border-radius: 1rem; width: 100%; max-width: 480px; padding: 1.5rem; }
.modal-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 1rem; }
.close-btn { background: none; border: none; font-size: 1.5rem; cursor: pointer; }
.btn-block { width: 100%; padding: 0.75rem; border: none; border-radius: 0.5rem; cursor: pointer; font-weight: 700; margin-top: 1rem; }
.toast-container { position: fixed; bottom: 1.5rem; right: 1.5rem; z-index: 200; }
.toast { background: #1e293b; color: #fff; padding: 0.75rem 1.25rem; border-radius: 0.5rem; font-size: 0.85rem; font-weight: 600; margin-top: 0.5rem; }

const MENU = [
  { id: 'item-1', name: 'Gourmet Truffle Burger', price: 14.99, desc: 'Aged cheddar, caramelized shallots, black truffle aioli', img: 'https://images.unsplash.com/photo-1568901346375-23c9450c58cd?w=500&auto=format&fit=crop&q=80' },
  { id: 'item-2', name: 'Woodfired Margherita Pizza', price: 16.50, desc: 'San Marzano tomatoes, buffalo mozzarella, fresh basil', img: 'https://images.unsplash.com/photo-1574071318508-1cdbab80d002?w=500&auto=format&fit=crop&q=80' },
  { id: 'item-3', name: 'Wild Salmon Bowl', price: 15.25, desc: 'Alaskan salmon, quinoa, avocado, citrus ponzu', img: 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=500&auto=format&fit=crop&q=80' },
  { id: 'item-4', name: 'Detox Green Juice', price: 6.50, desc: 'Kale, green apple, cucumber, ginger, lemon', img: 'https://images.unsplash.com/photo-1613478223719-2ab802602423?w=500&auto=format&fit=crop&q=80' }
];

let cart = [];

function renderMenu() {
  const grid = document.getElementById('food-grid');
  if (!grid) return;
  grid.innerHTML = MENU.map(function (item) {
    return (
      '<div class="food-item-card">' +
      '<img src="' + item.img + '" alt="' + item.name + '" class="food-item-thumb">' +
      '<div class="food-item-body">' +
      '<h4 class="food-item-title">' + item.name + '</h4>' +
      '<p class="food-item-desc">' + item.desc + '</p>' +
      '<div class="food-item-foot">' +
      '<span class="food-item-price">$' + item.price.toFixed(2) + '</span>' +
      '<button class="add-btn" onclick="addToCart(\'' + item.id + '\')">+ Add</button>' +
      '</div></div></div>'
    );
  }).join('');
}

function addToCart(id) {
  const item = MENU.find(function (m) { return m.id === id; });
  if (!item) return;
  const existing = cart.find(function (ci) { return ci.id === id; });
  if (existing) {
    existing.qty += 1;
  } else {
    cart.push({ id: item.id, name: item.name, price: item.price, qty: 1 });
  }
  updateCart();
  showToast('Added ' + item.name + ' to order!');
}

function updateCart() {
  const counter = document.getElementById('cart-counter');
  if (counter) counter.textContent = cart.reduce(function (acc, ci) { return acc + ci.qty; }, 0);
  const total = document.getElementById('cart-total');
  if (total) {
    const sum = cart.reduce(function (acc, ci) { return acc + ci.price * ci.qty; }, 0);
    total.textContent = '$' + sum.toFixed(2);
  }
}

function showToast(msg) {
  const cont = document.getElementById('toast-container');
  if (!cont) return;
  const t = document.createElement('div');
  t.className = 'toast';
  t.textContent = msg;
  cont.appendChild(t);
  setTimeout(function () { t.remove(); }, 2500);
}

document.addEventListener('DOMContentLoaded', function () {
  renderMenu();
  const toggle = document.getElementById('cart-toggle-btn');
  const modal = document.getElementById('cart-modal');
  const close = document.getElementById('close-cart-btn');
  if (toggle && modal) toggle.onclick = function () { modal.classList.add('open'); };
  if (close && modal) close.onclick = function () { modal.classList.remove('open'); };
});

:root {
  --primary: #EA580C;
  --primary-hover: #C2410C;
  --primary-light: #FFF7ED;
  --primary-border: #FED7AA;
  --accent: #10B981;
  --accent-light: #ECFDF5;
  --bg: #FAFAF9;
  --surface: #FFFFFF;
  --text-main: #1C1917;
  --text-muted: #78716C;
  --border: #E7E5E4;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -2px rgba(0, 0, 0, 0.06);
  --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.05);
  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 20px;
  --radius-full: 9999px;
  --font-sans: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
  --font-serif: 'Playfair Display', Georgia, serif;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg);
  color: var(--text-main);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

/* Navigation Bar */
.navbar {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
}

.nav-container {
  max-width: 1240px;
  margin: 0 auto;
  padding: 0.9rem 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
}

.brand-logo {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  text-decoration: none;
  font-weight: 800;
  font-size: 1.35rem;
  color: var(--text-main);
}

.brand-logo .brand-icon {
  font-size: 1.6rem;
}

.brand-logo .brand-name span {
  color: var(--primary);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 1.8rem;
}

.nav-links a {
  text-decoration: none;
  color: var(--text-muted);
  font-size: 0.92rem;
  font-weight: 600;
  transition: color 0.2s ease;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--primary);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.search-box {
  position: relative;
  display: flex;
  align-items: center;
}

.search-box input {
  padding: 0.55rem 1rem 0.55rem 2.2rem;
  font-size: 0.85rem;
  border-radius: var(--radius-full);
  border: 1px solid var(--border);
  background: var(--bg);
  outline: none;
  width: 200px;
  transition: all 0.2s ease;
  font-family: inherit;
}

.search-box input:focus {
  width: 250px;
  border-color: var(--primary);
  background: #fff;
  box-shadow: 0 0 0 3px rgba(234, 88, 12, 0.12);
}

.search-box .search-icon {
  position: absolute;
  left: 0.8rem;
  font-size: 0.8rem;
  pointer-events: none;
  opacity: 0.6;
}

.cart-btn {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.55rem 1rem;
  background: var(--primary-light);
  border: 1px solid var(--primary-border);
  color: var(--primary);
  font-weight: 700;
  font-size: 0.85rem;
  border-radius: var(--radius-full);
  cursor: pointer;
  transition: all 0.2s ease;
}

.cart-btn:hover {
  background: #ffedd5;
  transform: translateY(-1px);
}

.cart-badge {
  background: var(--primary);
  color: #fff;
  border-radius: var(--radius-full);
  font-size: 0.72rem;
  padding: 0.15rem 0.45rem;
  min-width: 18px;
  text-align: center;
}

/* Hero Section */
.hero-section {
  padding: 3.5rem 1.5rem 4rem;
  background: radial-gradient(circle at 10% 20%, #FFF7ED 0%, #FAFAF9 65%);
  overflow: hidden;
}

.hero-container {
  max-width: 1240px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  align-items: center;
  gap: 3.5rem;
}

.hero-pill {
  display: inline-block;
  padding: 0.35rem 0.9rem;
  background: #ffedd5;
  border: 1px solid var(--primary-border);
  color: var(--primary);
  border-radius: var(--radius-full);
  font-size: 0.82rem;
  font-weight: 700;
  margin-bottom: 1.2rem;
}

.hero-title {
  font-family: var(--font-serif);
  font-size: 3.2rem;
  line-height: 1.15;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 1.2rem;
}

.hero-title span {
  color: var(--primary);
  font-style: italic;
}

.hero-subtitle {
  font-size: 1.05rem;
  color: var(--text-muted);
  margin-bottom: 2rem;
  max-width: 540px;
}

.hero-cta-group {
  display: flex;
  gap: 1rem;
  margin-bottom: 2.5rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75rem 1.6rem;
  font-size: 0.92rem;
  font-weight: 700;
  border-radius: var(--radius-md);
  text-decoration: none;
  cursor: pointer;
  transition: all 0.2s ease;
  border: none;
  font-family: inherit;
}

.btn-primary {
  background: var(--primary);
  color: #fff;
  box-shadow: 0 4px 12px rgba(234, 88, 12, 0.25);
}

.btn-primary:hover {
  background: var(--primary-hover);
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(234, 88, 12, 0.35);
}

.btn-outline {
  background: #fff;
  color: var(--text-main);
  border: 1px solid var(--border);
}

.btn-outline:hover {
  border-color: var(--primary);
  color: var(--primary);
  background: var(--primary-light);
}

.btn-block {
  width: 100%;
}

.hero-stats {
  display: flex;
  gap: 2.5rem;
  padding-top: 1.5rem;
  border-top: 1px solid #e7e5e4;
}

.stat-item {
  display: flex;
  flex-direction: column;
}

.stat-number {
  font-size: 1.35rem;
  font-weight: 800;
  color: var(--text-main);
}

.stat-label {
  font-size: 0.8rem;
  color: var(--text-muted);
  font-weight: 600;
}

.hero-visual {
  display: flex;
  justify-content: center;
}

.food-card-floating {
  position: relative;
  background: #fff;
  border-radius: var(--radius-lg);
  padding: 1rem;
  box-shadow: var(--shadow-xl);
  border: 1px solid rgba(0, 0, 0, 0.05);
  max-width: 420px;
  width: 100%;
  transition: transform 0.3s ease;
}

.food-card-floating:hover {
  transform: translateY(-6px);
}

.hero-food-img {
  width: 100%;
  height: 260px;
  object-fit: cover;
  border-radius: var(--radius-md);
}

.food-badge {
  position: absolute;
  top: 1.7rem;
  left: 1.7rem;
  background: rgba(17, 24, 39, 0.85);
  color: #fff;
  backdrop-filter: blur(8px);
  padding: 0.35rem 0.8rem;
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 700;
}

.food-caption {
  padding: 1rem 0.5rem 0.5rem;
}

.food-caption h4 {
  font-size: 1.15rem;
  font-weight: 700;
  margin-bottom: 0.25rem;
}

.food-caption p {
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-bottom: 0.85rem;
}

.price-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.price-row .price {
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--primary);
}

.add-btn-quick {
  padding: 0.45rem 1rem;
  background: var(--text-main);
  color: #fff;
  border: none;
  border-radius: var(--radius-full);
  font-size: 0.8rem;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.2s ease;
}

.add-btn-quick:hover {
  background: var(--primary);
}

/* Menu Section */
.menu-section {
  padding: 4.5rem 1.5rem;
  max-width: 1240px;
  margin: 0 auto;
}

.section-header {
  text-align: center;
  margin-bottom: 2.5rem;
}

.section-tag {
  font-size: 0.82rem;
  font-weight: 800;
  color: var(--primary);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.section-title {
  font-family: var(--font-serif);
  font-size: 2.4rem;
  font-weight: 700;
  margin: 0.4rem 0 0.6rem;
}

.section-desc {
  font-size: 0.95rem;
  color: var(--text-muted);
  max-width: 520px;
  margin: 0 auto;
}

.category-filter-bar {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 0.6rem;
  margin-bottom: 2.5rem;
}

.filter-chip {
  padding: 0.55rem 1.15rem;
  border-radius: var(--radius-full);
  border: 1px solid var(--border);
  background: #fff;
  color: var(--text-main);
  font-size: 0.88rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
  font-family: inherit;
}

.filter-chip:hover {
  border-color: var(--primary-border);
  background: var(--primary-light);
}

.filter-chip.active {
  background: var(--primary);
  color: #fff;
  border-color: var(--primary);
  box-shadow: 0 4px 10px rgba(234, 88, 12, 0.22);
}

/* Food Grid */
.food-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(270px, 1fr));
  gap: 1.8rem;
}

.food-item-card {
  background: #fff;
  border-radius: var(--radius-md);
  border: 1px solid var(--border);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all 0.25s ease;
  display: flex;
  flex-direction: column;
}

.food-item-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
  border-color: #cbd5e1;
}

.food-item-thumb {
  width: 100%;
  height: 180px;
  object-fit: cover;
}

.food-item-body {
  padding: 1.15rem;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.food-item-rating {
  font-size: 0.78rem;
  color: #f59e0b;
  font-weight: 700;
  margin-bottom: 0.3rem;
}

.food-item-title {
  font-size: 1.05rem;
  font-weight: 700;
  margin-bottom: 0.35rem;
}

.food-item-desc {
  font-size: 0.82rem;
  color: var(--text-muted);
  margin-bottom: 1.2rem;
  flex: 1;
  line-height: 1.5;
}

.food-item-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 0.8rem;
  border-top: 1px solid #f5f5f4;
}

.food-item-price {
  font-size: 1.15rem;
  font-weight: 800;
  color: var(--text-main);
}

.btn-add-cart {
  padding: 0.45rem 1rem;
  border-radius: var(--radius-full);
  background: var(--primary-light);
  border: 1px solid var(--primary-border);
  color: var(--primary);
  font-size: 0.82rem;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.2s ease;
}

.btn-add-cart:hover {
  background: var(--primary);
  color: #fff;
}

/* Promo Banner */
.promo-section {
  padding: 3rem 1.5rem;
  max-width: 1240px;
  margin: 0 auto;
}

.promo-card {
  background: linear-gradient(135deg, #1C1917 0%, #292524 100%);
  color: #fff;
  border-radius: var(--radius-lg);
  padding: 3rem 2rem;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.promo-card::before {
  content: '';
  position: absolute;
  top: -50px;
  right: -50px;
  width: 200px;
  height: 200px;
  background: radial-gradient(circle, rgba(234, 88, 12, 0.4) 0%, transparent 70%);
  border-radius: 50%;
}

.promo-tag {
  display: inline-block;
  padding: 0.3rem 0.8rem;
  background: rgba(234, 88, 12, 0.25);
  color: #fb923c;
  border: 1px solid rgba(234, 88, 12, 0.5);
  border-radius: var(--radius-full);
  font-size: 0.8rem;
  font-weight: 700;
  margin-bottom: 1rem;
}

.promo-card h2 {
  font-family: var(--font-serif);
  font-size: 2.2rem;
  margin-bottom: 0.8rem;
}

.promo-card p {
  font-size: 0.95rem;
  color: #d6d3d1;
  max-width: 480px;
  margin: 0 auto 1.8rem;
}

/* Modal Cart */
.modal-backdrop {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(4px);
  z-index: 200;
  align-items: center;
  justify-content: center;
  padding: 1.5rem;
}

.modal-backdrop.open {
  display: flex;
}

.modal-card {
  background: #fff;
  border-radius: var(--radius-lg);
  width: 100%;
  max-width: 480px;
  max-height: 85vh;
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow-xl);
  overflow: hidden;
  animation: modalSlide 0.25s ease-out;
}

@keyframes modalSlide {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

.modal-header {
  padding: 1.2rem 1.5rem;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.modal-title-group {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.close-btn {
  background: none;
  border: none;
  font-size: 1.5rem;
  line-height: 1;
  color: var(--text-muted);
  cursor: pointer;
}

.cart-items-list {
  padding: 1rem 1.5rem;
  overflow-y: auto;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 0.8rem;
}

.cart-empty-message {
  text-align: center;
  padding: 2.5rem 0;
  color: var(--text-muted);
  font-size: 0.9rem;
}

.cart-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.6rem 0;
  border-bottom: 1px dashed var(--border);
}

.cart-row-info h5 {
  font-size: 0.92rem;
  font-weight: 700;
}

.cart-row-info span {
  font-size: 0.82rem;
  color: var(--text-muted);
}

.cart-row-controls {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.qty-btn {
  width: 24px;
  height: 24px;
  border-radius: var(--radius-full);
  border: 1px solid var(--border);
  background: #fff;
  cursor: pointer;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
}

.modal-footer {
  padding: 1.2rem 1.5rem;
  border-top: 1px solid var(--border);
  background: var(--bg);
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.cart-summary-line {
  display: flex;
  justify-content: space-between;
  font-size: 0.88rem;
  color: var(--text-muted);
}

.cart-summary-line.total {
  font-size: 1.15rem;
  font-weight: 800;
  color: var(--text-main);
  padding-top: 0.4rem;
  border-top: 1px solid var(--border);
}

.free-text {
  color: var(--accent);
  font-weight: 700;
}

/* Toast */
.toast-container {
  position: fixed;
  bottom: 1.5rem;
  right: 1.5rem;
  z-index: 300;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.toast {
  background: #1C1917;
  color: #fff;
  padding: 0.75rem 1.2rem;
  border-radius: var(--radius-md);
  font-size: 0.85rem;
  font-weight: 600;
  box-shadow: var(--shadow-xl);
  display: flex;
  align-items: center;
  gap: 0.5rem;
  animation: toastFade 0.3s ease-out;
}

@keyframes toastFade {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Footer */
.footer {
  background: #1C1917;
  color: #fff;
  padding: 3.5rem 1.5rem 1.5rem;
  margin-top: 3rem;
}

.footer-container {
  max-width: 1240px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 3rem;
  padding-bottom: 2.5rem;
  border-bottom: 1px solid #292524;
}

.footer-logo {
  color: #fff;
  margin-bottom: 1rem;
}

.footer-text {
  font-size: 0.88rem;
  color: #a8a29e;
  max-width: 320px;
}

.footer-col h4 {
  font-size: 0.95rem;
  font-weight: 700;
  margin-bottom: 1rem;
  color: #fff;
}

.footer-col p {
  font-size: 0.85rem;
  color: #a8a29e;
  margin-bottom: 0.5rem;
}

.footer-bottom {
  max-width: 1240px;
  margin: 1.5rem auto 0;
  text-align: center;
  font-size: 0.8rem;
  color: #78716c;
